cypress_script:
describe('Mobile Viewport Product Browsing via Burger Menu', () => {
  it('should open and close the burger menu successfully', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[id="react-burger-menu-btn"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('be.visible');
    cy.get('[id="react-burger-cross-btn"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').should('not.exist');
  });

  it('should not navigate when clicking the burger menu link without proper login', () => {
    cy.visit('https://www.saucedemo.com/inventory.html');
    cy.get('[id="react-burger-menu-btn"]').click();
    cy.get('[data-test="inventory-sidebar-link"]').click();
    cy.url().should('eq', 'https://www.saucedemo.com/inventory.html');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Mobile Viewport Product Browsing via Burger Menu', () => {
  test('should open and close the burger menu successfully', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[id="react-burger-menu-btn"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).toBeVisible();
    await page.click('[id="react-burger-cross-btn"]');
    await expect(page.locator('[data-test="inventory-sidebar-link"]')).toBeHidden();
  });

  test('should not navigate when clicking the burger menu link without proper login', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/inventory.html');
    await page.click('[id="react-burger-menu-btn"]');
    await page.click('[data-test="inventory-sidebar-link"]');
    await expect(page).toHaveURL('https://www.saucedemo.com/inventory.html');
  });
});
